using System.IO.Compression;
using System.Xml;
using System.Xml.Linq;

namespace wwwmmm.Integrations;

/// <summary>Adapter for clisonix.com/excel-core/excel_reporting_api.py.</summary>
public sealed class ClisonixExcelCoreBridge : IDisposable
{
    private readonly BridgeTransport _transport;

    public ClisonixExcelCoreBridge(BridgeConnection connection) : this(connection, null) { }
    internal ClisonixExcelCoreBridge(BridgeConnection connection, HttpMessageHandler? handler) =>
        _transport = new(connection, handler);

    /// <summary>Downloads the real LAGTER workbook generated by Excel Core. Does not claim PDF export.</summary>
    public async Task<byte[]> ExportLagterAsync(CancellationToken cancellationToken = default)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, "api/lagter/v1/export");
        var data = await _transport.SendBytesAsync(request, false,
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", 10 * 1024 * 1024, cancellationToken);
        ValidateWorkbook(data);
        return data;
    }

    private static void ValidateWorkbook(byte[] data)
    {
        try
        {
            using var stream = new MemoryStream(data, writable: false);
            using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
            var contentTypes = ReadXml(archive, "[Content_Types].xml");
            var workbook = ReadXml(archive, "xl/workbook.xml");
            XNamespace contentNs = "http://schemas.openxmlformats.org/package/2006/content-types";
            XNamespace sheetNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
            if (contentTypes.Root?.Name != contentNs + "Types" ||
                !contentTypes.Root.Elements(contentNs + "Override").Any(x =>
                    (string?)x.Attribute("PartName") == "/xl/workbook.xml" &&
                    (string?)x.Attribute("ContentType") == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml") ||
                workbook.Root?.Name != sheetNs + "workbook" ||
                !workbook.Descendants(sheetNs + "sheet").Any() ||
                !archive.Entries.Any(x => x.FullName.StartsWith("xl/worksheets/", StringComparison.Ordinal) && x.FullName.EndsWith(".xml", StringComparison.Ordinal)))
                throw new BridgeException("Excel Core returned an invalid XLSX workbook.");
        }
        catch (Exception ex) when (ex is InvalidDataException or XmlException or IOException)
        {
            throw new BridgeException("Excel Core returned an unreadable XLSX workbook.");
        }
    }

    private static XDocument ReadXml(ZipArchive archive, string name)
    {
        var entry = archive.GetEntry(name);
        if (entry is null || entry.Length > 1024 * 1024)
            throw new BridgeException("Excel Core workbook metadata is missing or too large.");
        using var stream = entry.Open();
        using var reader = XmlReader.Create(stream, new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            XmlResolver = null,
            MaxCharactersInDocument = 1024 * 1024
        });
        return XDocument.Load(reader);
    }

    public void Dispose() => _transport.Dispose();
}
